import sys

def largest(s, k):
    arr = list(s)
    n = len(arr)
    best = [s]
    seen = set()

    def rec(i, k):
        if i == n or k == 0:
            return
        key = (''.join(arr), i, k)
        if key in seen:
            return
        seen.add(key)
        m = max(arr[i:])
        if m != arr[i]:
            for j in range(i + 1, n):
                if arr[j] == m:
                    arr[i], arr[j] = arr[j], arr[i]
                    cur = ''.join(arr)
                    if cur > best[0]:
                        best[0] = cur
                    rec(i + 1, k - 1)
                    arr[i], arr[j] = arr[j], arr[i]
        else:
            rec(i + 1, k)

    rec(0, k)
    return best[0]

def count_true(expr):
    MOD = 10**9 + 7
    sym = expr[0::2]
    ops = expr[1::2]
    m = len(sym)
    T = [[0] * m for _ in range(m)]
    F = [[0] * m for _ in range(m)]
    for i in range(m):
        if sym[i] == 'T':
            T[i][i] = 1
        else:
            F[i][i] = 1
    for L in range(2, m + 1):
        for i in range(m - L + 1):
            j = i + L - 1
            t = f = 0
            for k in range(i, j):
                lt = T[i][k]
                lf = F[i][k]
                rt = T[k + 1][j]
                rf = F[k + 1][j]
                tot = (lt + lf) * (rt + rf)
                o = ops[k]
                if o == '&':
                    a = lt * rt
                elif o == '|':
                    a = tot - lf * rf
                else:
                    a = lt * rf + lf * rt
                t += a
                f += tot - a
            T[i][j] = t % MOD
            F[i][j] = f % MOD
    return T[0][m - 1]

def main():
    s, k, expr = sys.stdin.read().split()
    print(largest(s, int(k)))
    print(count_true(expr))

main()

