def gen(rng):
    def rexpr(m, bias=None):
        out = []
        for i in range(m):
            if bias:
                out.append(rng.choice(bias[0]))
            else:
                out.append(rng.choice('TF'))
            if i < m - 1:
                out.append(rng.choice(bias[1]) if bias else rng.choice('&|^'))
        return ''.join(out)

    def rnum(n, alpha='0123456789'):
        d = rng.choice([c for c in alpha if c != '0'] or ['1'])
        return d + ''.join(rng.choice(alpha) for _ in range(n - 1))

    def fmt(s, k, e):
        return f'{s} {k}\n{e}'

    tests = [fmt('1234', 1, 'T^F&F'), fmt('7599', 2, 'T|F^T&T'), fmt('9876', 3, 'F'), fmt('5', 0, 'T'), fmt('5', 3, 'F'), fmt('10', 1, 'T&F'), fmt('100', 1, 'F|T'),
             fmt('1230', 0, 'T^T'), fmt('999', 5, 'T&T&T'), fmt('1111', 2, 'F^F^F^F'), fmt('21', 1, 'T|T|T'), fmt('4321', 2, 'F&F&F&F')]
    for _ in range(14):
        n = rng.randint(2, 6)
        k = rng.randint(0, 4)
        alpha = rng.choice(('01', '0129', '0123456789', '19'))
        tests.append(fmt(rnum(n, alpha), k, rexpr(rng.randint(1, 8))))
    for _ in range(4):
        m = rng.randint(3, 8)
        tests.append(fmt(rnum(rng.randint(3, 6)), rng.randint(1, 4), rexpr(m, ('T', '&|^'))))
        tests.append(fmt(rnum(rng.randint(3, 6)), rng.randint(1, 4), rexpr(m, ('F', '&|^'))))
    # mid-size: only the reference can handle these (no brute: long strings)
    for _ in range(3):
        tests.append(fmt(rnum(15, rng.choice(('019', '0123456789', '129'))), rng.randint(3, 15), rexpr(rng.randint(30, 80))))
    # max size
    tests.append(fmt(rnum(15), 15, rexpr(200)))
    tests.append(fmt('1' + '9' * 7 + '1' * 7, 7, rexpr(200, ('T', '&|^'))))
    tests.append(fmt(rnum(15, '019'), 6, rexpr(200, ('TF', '^'))))
    tests.append(fmt('123456789987654', 15, rexpr(200, ('T', '|^'))))
    return tests

